    ]
  },
  "industry": {
    "industry": "Custom Metal Fabrication and Manufacturing",
    "activities": [
      "Custom metal fabrication for commercial, industrial, and residential applications",
      "Custom metal signs, railings, stairs, gates, fences, and awnings",
      "Truck accessories, upfitting, and fabricated steel tanks",
      "Structural steel fabrication and architectural metalwork",
      "Product development, manufacturing, machining, and CNC water jet cutting",
      "In-house painting and partnered powder coating"
    ],
    "claims": [
      {
        "statement": "Boise Metal Works provides custom metal fabrication and manufacturing solutions for commercial, industrial, and residential customers.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": "Boise Metal Works provides custom metal fabrication and manufacturing solutions for commercial, industrial, and residential applications."
      },
      {
        "statement": "The company handles custom signs, truck accessories and tanks, awnings, product development, steel tanks, gates, fences, stairs, railing, structural fabrication, machining, and water jet cutting.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": "Services Custom Metal Signs Custom Truck Accessories & Tanks Custom Metal Awnings Product Development & Manufacturing Fabricated Steel Tanks Shop Equipment Capabilities Metal Gates & Fences"
      },
      {
        "statement": "The company works with steel, aluminum, stainless steel, alloy, galvanized metal, and copper.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/metals-fabrication-industry-infomation/",
        "quote": "A: Steel, Aluminum, Stainless Steel, Alloy, Galvanized, and Copper."
      },
      {
        "statement": "Boise Metal Works is a custom metal fabrication and manufacturing shop rather than an HVAC, plumbing, or electrical home-service contractor.",
        "label": "inference",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.boisemetalworks.com/",
    "claims": [
      {
        "statement": "The official website states a standard shop rate of $95 per hour, separate from machining and water jet rates.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/metals-fabrication-industry-infomation/",
        "quote": "A: Our shop rate is $95 an hour and is subject to change. This is separate from our machining and water jet rates."
      },
      {
        "statement": "The company offers both shop and field welding capabilities, including Hardwire, Dual Shield, Tig, and Stick welding.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/metal-fabrication-shop-capacities/",
        "quote": "Hardwire, Dual Shield, Tig and Stick, we have both Shop and Field capabilities"
      },
      {
        "statement": "The company assigns a single point of contact to customers from project design through delivery.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": "Your dedicated, Boise Metal Works point of contact is committed for the life of your project, from design to delivery."
      },
      {
        "statement": "The website footer credits Thrive Web Designs for the website design.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/",
        "quote": "©2026 Boise Metal Works, All Rights Reserved. Website Design Boise by Thrive Web Designs"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The FAQ page references commercial and residential building code requirements for stair rise and handrail dimensions.",
        "label": "fact",
        "sourceUrl": "https://www.boisemetalworks.com/metals-fabrication-industry-infomation/",
        "quote": "A: Maximum rise is 7″ per commercial code 7 1/4″ per residential code."
      }
    ],
    "limitations": "No contractor license numbers, structural welding certifications, or Idaho business registration numbers are stated on the pages read."
  },
